solution.code:
class Money:
    def __init__(self, amount):
        self.amount = amount

    def __add__(self, other):
        return Money(self.amount + other.amount)

    def __str__(self):
        return str(self.amount) + " INR"


a = Money(50)
b = Money(70)
print(a + b)
